// maxToolRounds — потолок раундов tool-use на один Ask (защита от зацикливания,
// в духе defaultReworkRounds из дня 15).
const maxToolRounds = 8

func NewAgent(client anthropic.Client, model anthropic.Model, mem *Memory) *Agent {
	return &Agent{client: client, model: model, maxTokens: 1024, mem: mem,
		base: "Ты ассистент-помощник разработчика."}
}

// SetMCP подключает MCP-инструменты к агенту (день 17). Если задано — список
// инструментов кладётся в каждый запрос, и модель может их вызывать (tool-use).
func (a *Agent) SetMCP(m *MCPTools) { a.mcp = m }

// SetLazyTools включает ленивую загрузку схем (день 20, усиление): старт с каталога
// серверов, схемы тулов сервера подмешиваются только после load_tools.
func (a *Agent) SetLazyTools(on bool) { a.lazyTools = on }

func (a *Agent) SetMaxTokens(n int64) {
	if n > 0 {
		a.maxTokens = n
	}
}

// SetProfile делает профиль активным: его содержимое становится долговременным слоем.
func (a *Agent) SetProfile(p Profile) {
	a.profileID = p.ID
	a.mem.SetLongDoc(p.Doc)
}

// Ask: собирает запрос из выбранных слоёв памяти (включая профиль как long-term),
// диалог пишет в short-term.
func (a *Agent) Ask(ctx context.Context, query string, p Policy) (Reply, error) {
	return a.ask(ctx, query, p, true)
}

// AskOnce: разовый запрос без записи диалога (для сравнения профилей).
func (a *Agent) AskOnce(ctx context.Context, query string, p Policy) (Reply, error) {
	return a.ask(ctx, query, p, false)
}

func (a *Agent) ask(ctx context.Context, query string, p Policy, store bool) (Reply, error) {
	// enforcement инвариантов ДО основного запроса
	var llmVerdict string
	if a.inv != nil {
		if v := EnforceCode(a.inv, query); !v.Allowed {
			r := a.refuse(v)
			r.RefusedBy = "код"
			return r, nil
		}
		if a.llmCheck {
			v, err := EnforceLLM(ctx, a.client, a.model, a.inv, query)
			if err == nil {
				llmVerdict = v.Raw
				if !v.Allowed {
					r := a.refuse(v)
					r.RefusedBy = "LLM"
					r.CheckVerdict = v.Raw
					return r, nil
				}
			}
		}
	}
	system, msgs, used := a.mem.Build(query, p)
	system = append([]anthropic.TextBlockParam{{Text: a.base}}, system...)
	if a.inv != nil {
		if block := a.inv.Render(); block != "" {
			system = append(system, anthropic.TextBlockParam{Text: "[ИНВАРИАНТЫ]\n" + block})
		}
	}

	params := anthropic.MessageNewParams{
		Model: a.model, MaxTokens: a.maxTokens, System: system, Messages: msgs,
	}
	if a.mcp != nil {
		if a.lazyTools {
			params.Tools = a.mcp.CatalogTools() // только каталог серверов (ленивый режим)
		} else {
			params.Tools = a.mcp.Tools() // все тулы сразу (жадный режим, базовый день 20)
		}
	}

	// Цикл tool-use: пока модель просит инструменты — выполняем их через MCP
	// (с проверкой инвариантов на КАЖДЫЙ вызов) и возвращаем результаты.
	var inTok, outTok int64
	for round := 0; round < maxToolRounds; round++ {
		msg, err := a.client.Messages.New(ctx, params)
		if err != nil {
			return Reply{}, fmt.Errorf("agent: request failed: %w", err)
		}
		inTok += msg.Usage.InputTokens
		outTok += msg.Usage.OutputTokens

		// Нет инструментов или модель не просит их — это финальный ответ.
		if a.mcp == nil || string(msg.StopReason) != string(anthropic.StopReasonToolUse) {
			text := collectText(msg)
			if text == "" {
				return Reply{}, errors.New("agent: empty response")
			}
			if store {
				a.mem.Dialog(roleUser, query)
				a.mem.Dialog(roleAssistant, text)
			}
			return Reply{
				Text: text, UsedLayers: used, ProfileID: a.profileID,
				Input: inTok, Output: outTok,
				CheckVerdict: llmVerdict, StopReason: string(msg.StopReason),
			}, nil
		}

		// Раунд tool-use: добавляем ход ассистента (с tool_use) и выполняем вызовы.
		params.Messages = append(params.Messages, msg.ToParam())
		var results []anthropic.ContentBlockParamUnion
		for _, block := range msg.Content {
			if block.Type != "tool_use" {
				continue
			}
			tu := block.AsToolUse()
			// Мета-тул ленивой загрузки: подмешиваем схемы тулов запрошенного сервера.
			if a.lazyTools && tu.Name == LoadToolsName {
				added, summary := a.mcp.LoadServer(tu.Input)
				params.Tools = appendNewTools(params.Tools, added)
				fmt.Printf("[lazy] load_tools %s → подмешано тулов: %d\n", oneLine(string(tu.Input), 60), len(added))
				results = append(results, anthropic.NewToolResultBlock(tu.ID, summary, false))
				continue
			}
			out, isErr := a.runTool(ctx, tu.Name, tu.Input)
			results = append(results, anthropic.NewToolResultBlock(tu.ID, out, isErr))
		}
		params.Messages = append(params.Messages, anthropic.NewUserMessage(results...))
	}
	return Reply{}, errors.New("agent: превышен лимит раундов tool-use")
}

// runTool применяет инварианты к НАМЕРЕНИЮ вызвать инструмент и, если разрешено,
// выполняет его через MCP. Отказ возвращается модели как tool_result с is_error,
// чтобы агент не мог обойти инвариант через инструмент и видел причину отказа.
func (a *Agent) runTool(ctx context.Context, name string, input json.RawMessage) (string, bool) {
	intent := name + " " + string(input)
	if a.inv != nil {
		if v := EnforceCode(a.inv, intent); !v.Allowed {
			fmt.Printf("[инвариант/код] вызов %s отклонён: %s\n", name, v.Reason)
			return "ОТКАЗ (инвариант, проверка кодом): " + v.Reason, true
		}
		if a.llmCheck {
			if v, err := EnforceLLM(ctx, a.client, a.model, a.inv, intent); err == nil && !v.Allowed {
				fmt.Printf("[инвариант/LLM] вызов %s отклонён: %s\n", name, v.Reason)
				return "ОТКАЗ (инвариант, LLM): " + v.Reason, true
			}
		}
	}
	fmt.Printf("[agent→mcp] %s %s\n", name, oneLine(string(input), 160))
	out, isErr := a.mcp.Call(ctx, name, input)
	fmt.Printf("[mcp→agent] %s\n", oneLine(out, 200))
	return out, isErr
}

// refuse формирует отказ агента с объяснением, какой инвариант нарушен.
func (a *Agent) refuse(v Verdict) Reply {
	via := "LLM-проверка"
	if v.ByCode {
		via = "проверка кодом"
	}
	text := "Не могу выполнить: запрос нарушает инвариант. " + v.Reason +
		"\n(" + via + "). Предложи вариант, не нарушающий инвариант, или сними ограничение явно."
	return Reply{Text: text, ProfileID: a.profileID, Refused: true, Violated: v.Violated}
}

func collectText(msg *anthropic.Message) string {
	var b strings.Builder
	for _, block := range msg.Content {
		if block.Type == "text" {
			b.WriteString(block.Text)
		}
	}
	return b.String()
}

func layersString(ls []Layer) string {
	if len(ls) == 0 {
		return "нет (stateless)"
	}
	parts := make([]string, len(ls))
	for i, l := range ls {
		parts[i] = l.String()
	}
	return strings.Join(parts, ", ")
}

// ArtifactCheck — результат лёгкой детерминированной проверки результата этапа.
// НЕ компилирует код и НЕ требует наличия кода: ловит только объективные признаки
// неполного/оборванного ответа. Содержательную проверку делает рой.
type ArtifactCheck struct {
	OK        bool   // результат пригоден для содержательной валидации (роя)
	Truncated bool   // ответ оборван (max_tokens или незакрытый блок кода)
	Empty     bool   // результат пустой
	Reason    string // причина при OK=false
}

// CheckResult — детерминированная проверка результата этапа.
// stopReason — из API (end_turn | max_tokens | …). Костыля с `go build` нет.
func CheckResult(text, stopReason string) ArtifactCheck {
	trimmed := strings.TrimSpace(text)
	if trimmed == "" {
		return ArtifactCheck{Empty: true, Reason: "пустой результат этапа"}
	}
	// 1) Штатный сигнал API: модель упёрлась в лимит токенов → ответ оборван.
	if stopReason == "max_tokens" {
		return ArtifactCheck{Truncated: true,
			Reason: "ответ оборван по лимиту токенов (stop_reason=max_tokens)"}
	}
	// 2) Незакрытый блок кода ```…``` — тоже признак обрыва (если оборвалось не по токенам).
	if strings.Count(text, "```")%2 != 0 {
		return ArtifactCheck{Truncated: true,
			Reason: "незакрытый блок кода (```) — результат неполный"}
	}
	return ArtifactCheck{OK: true}
}

import (
	"context"
	"fmt"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
)

// Verdict — результат проверки запроса на конфликт с инвариантами.
type Verdict struct {
	Allowed  bool
	Violated []string // id/описания нарушенных
	Reason   string   // объяснение отказа
	ByCode   bool     // сработала детерминированная проверка
	Decision string   // сырой DECISION от LLM-проверяющего (ALLOW/DENY)
	Raw      string   // сырой ответ LLM-проверяющего (для прозрачности)
}

// EnforceCode — способ 1: детерминированная проверка по стоп-словам (быстро, дёшево).
func EnforceCode(set *InvariantSet, query string) Verdict {
	hit := set.CheckCode(query)
	if len(hit) == 0 {
		return Verdict{Allowed: true}
	}
	var ids, reasons []string
	for _, inv := range hit {
		ids = append(ids, inv.ID)
		reasons = append(reasons, inv.Text)
	}
	return Verdict{
		Allowed:  false,
		Violated: ids,
		Reason:   "Запрос нарушает инвариант(ы): " + strings.Join(reasons, "; "),
		ByCode:   true,
	}
}

// EnforceLLM — способ 2: семантическая проверка запроса моделью.
// Возвращает вердикт ALLOW/DENY + объяснение. Эти способы не взаимоисключают друг друга.
func EnforceLLM(ctx context.Context, client anthropic.Client, model anthropic.Model, set *InvariantSet, query string) (Verdict, error) {
	rules := set.Render()
	sys := "Ты — проверяющий. Тебе даны инварианты и запрос пользователя. " +
		"Реши, нарушает ли ВЫПОЛНЕНИЕ запроса хотя бы один инвариант. " +
		"Ответь строго в формате:\nDECISION: ALLOW|DENY\nREASON: <одно предложение, какой инвариант и почему>"
	user := "[ИНВАРИАНТЫ]\n" + rules + "\n[ЗАПРОС]\n" + query

	msg, err := client.Messages.New(ctx, anthropic.MessageNewParams{
		Model: model, MaxTokens: 200,
		System:   []anthropic.TextBlockParam{{Text: sys}},
		Messages: []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock(user))},
	})
	if err != nil {
		return Verdict{}, fmt.Errorf("enforce(llm): %w", err)
	}
	out := collectText(msg)
	decision, reason := parseVerdict(out)
	return Verdict{
		Allowed:  decision == "ALLOW",
		Reason:   reason,
		Decision: decision,
		Raw:      strings.TrimSpace(out),
	}, nil
}

func parseVerdict(s string) (decision, reason string) {
	decision = "ALLOW"
	for _, line := range strings.Split(s, "\n") {
		l := strings.TrimSpace(line)
		up := strings.ToUpper(l)
		if strings.HasPrefix(up, "DECISION:") {
			if strings.Contains(up, "DENY") {
				decision = "DENY"
			} else {
				decision = "ALLOW"
			}
		}
		if strings.HasPrefix(up, "REASON:") {
			reason = strings.TrimSpace(l[len("REASON:"):])
		}
	}
	return decision, reason
}

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Invariant — ограничение, которое агент не имеет права нарушать.
// Kind: "system" (подкапотное) или "user" (заданное пользователем).
type Invariant struct {
	ID   string   `json:"id"`
	Text string   `json:"text"` // человекочитаемое правило
	Kind string   `json:"kind"` // system | user
	Deny []string `json:"deny"` // стоп-слова для детерминированной проверки (lower-case)
}

// InvariantSet хранит инварианты ОТДЕЛЬНО от диалога (свой файл invariants.json).
type InvariantSet struct {
	dir  string
	list []Invariant
}

func NewInvariantSet(dir string) *InvariantSet {
	s := &InvariantSet{dir: dir}
	s.list = append(s.list, systemInvariants()...)
	s.load() // пользовательские поверх системных
	return s
}

// systemInvariants — подкапотные ограничения (юзер может о них не знать).
func systemInvariants() []Invariant {
	return []Invariant{
		{ID: "stack-go", Kind: "system",
			Text: "Стек только Go. Не предлагать другие языки (Java, Python, Rust…) без явного снятия инварианта.",
			Deny: []string{"на java", "на python", "на rust", "напиши на c#", "перепиши на java"}},
		{ID: "no-secrets", Kind: "system",
			Text: "Не хардкодить секреты/ключи в коде; только через переменные окружения.",
			Deny: []string{"захардкоди ключ", "впиши пароль в код", "secret в коде"}},
	}
}

func (s *InvariantSet) Add(text string, deny []string) Invariant {
	inv := Invariant{
		ID:   fmt.Sprintf("user-%d", len(s.list)+1),
		Text: text, Kind: "user", Deny: lowerAll(deny),
	}
	s.list = append(s.list, inv)
	_ = s.save()
	return inv
}

// Render — блок для System prompt: агент обязан учитывать эти правила.
func (s *InvariantSet) Render() string {
	if len(s.list) == 0 {
		return ""
	}
	var b strings.Builder
	b.WriteString("Ты ОБЯЗАН соблюдать инварианты ниже. Если запрос им противоречит — ")
	b.WriteString("откажись и объясни, какой инвариант нарушается; предложи допустимую альтернативу.\n")
	for _, inv := range s.list {
		fmt.Fprintf(&b, "- [%s] %s\n", inv.ID, inv.Text)
	}
	return b.String()
}

// CheckCode — детерминированная проверка (способ 1): ищет стоп-слова в тексте.
// Возвращает нарушенные инварианты.
func (s *InvariantSet) CheckCode(text string) []Invariant {
	low := strings.ToLower(text)
	var hit []Invariant
	for _, inv := range s.list {
		for _, d := range inv.Deny {
			if d != "" && strings.Contains(low, d) {
				hit = append(hit, inv)
				break
			}
		}
	}
	return hit
}

func (s *InvariantSet) load() {
	if s.dir == "" {
		return
	}
	var user []Invariant
	if err := readJSON(filepath.Join(s.dir, "invariants.json"), &user); err == nil {
		s.list = append(s.list, user...)
	}
}

func (s *InvariantSet) save() error {
	if s.dir == "" {
		return nil
	}
	var user []Invariant
	for _, inv := range s.list {
		if inv.Kind == "user" {
			user = append(user, inv)
		}
	}
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		return err
	}
	return writeJSON(filepath.Join(s.dir, "invariants.json"), user)
}

func lowerAll(ss []string) []string {
	out := make([]string, 0, len(ss))
	for _, s := range ss {
		out = append(out, strings.ToLower(strings.TrimSpace(s)))
	}
	return out
}

// swarmStageOf парсит значение флага -swarm-stage в TaskState.
func swarmStageOf(v string) TaskState {
	if v == "planning" {
		return StatePlanning
	}
	return StateValidation
}

func sourceDir() string {
	if _, file, _, ok := runtime.Caller(0); ok {
		return filepath.Dir(file)
	}
	return "."
}

func main() {
	reportMode := flag.Bool("report", false, "демонстрация (память + профили) и выход")
	memDir := flag.String("mem", filepath.Join(sourceDir(), "memory"), "каталог памяти (short-term/working)")
	profilesDir := flag.String("profiles", filepath.Join(sourceDir(), "profiles"), "каталог профилей (<id>.md)")
	active := flag.String("profile", "senior-go", "активный профиль")
	confirm := flag.Bool("confirm", false, "спрашивать подтверждение перед переходом этапа (пауза)")
	llmCheck := flag.Bool("llm-check", false, "включить семантическую проверку инвариантов через LLM")
	swarmOn := flag.Bool("swarm", false, "включить рой ревьюеров")
	swarmStage := flag.String("swarm-stage", "validation", "этап роя: planning | validation")
	maxTokens := flag.Int64("max-tokens", 4096, "лимит токенов ответа модели")
	watchSec := flag.Int("watch", 0, "день 18: режим 24/7 — печатать сводку каждые N сек (0 = обычный REPL)")
	track := flag.String("track", "Berlin,Sofia", "watch: города через запятую для фонового сбора")
	interval := flag.Int("interval", 30, "watch: период фонового сбора на сервере, сек")
	lazy := flag.Bool("lazy", true, "день 20: ленивая загрузка схем тулов (каталог серверов → load_tools). false = слать все схемы сразу")
	flag.Parse()

	if err := godotenv.Load(); err != nil {
		log.Fatalf("failed to load .env: %s", err.Error())
	}
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	client := anthropic.NewClient()
	model := anthropic.ModelClaudeOpus4_8

	if *reportMode {
		if err := runReport(ctx, client, *profilesDir, *memDir, *swarmOn, *swarmStage, *maxTokens); err != nil {
			log.Fatalf("report failed: %s", err.Error())
		}
		return
	}

	mem, _ := LoadMemory(*memDir)
	store := NewProfileStore(*profilesDir)
	agent := NewAgent(client, model, mem)
	if p, err := store.Load(*active); err == nil {
		agent.SetProfile(p)
	} else {
		log.Printf("профиль %q не найден, работаю без профиля", *active)
	}
	inv := NewInvariantSet(*memDir)
	agent.SetInvariants(inv)
	agent.SetLLMCheck(*llmCheck)
	agent.SetMaxTokens(*maxTokens)

	// День 17: инструменты доступны агенту всегда, вызовы проходят через инварианты.
	// День 20: оркестрация НЕСКОЛЬКИХ MCP-серверов разной природы.
	servers := []ServerSpec{
		{Name: "weather", Purpose: "погода, геокодинг, фоновое слежение за городами",
			Cmd: []string{"go", "run", filepath.Join(sourceDir(), "weatherserver")}},
		{Name: "notes", Purpose: "файловое хранилище: сохранить/прочитать/список/удалить",
			Cmd: []string{"go", "run", filepath.Join(sourceDir(), "notesserver")}},
	}
	mcptools, mcpStop, err := ConnectMCP(ctx, servers)
	if err != nil {
		log.Printf("MCP недоступен (%v) — работаю без инструментов", err)
	} else {
		defer mcpStop()
		agent.SetMCP(mcptools)
		agent.SetLazyTools(*lazy)
		mode := "жадный (все схемы сразу)"
		if *lazy {
			mode = "ленивый (каталог серверов → load_tools)"
		}
		fmt.Printf("MCP: %d тул(ов) с %d серверов · режим схем: %s\n  %s\n",
			mcptools.Len(), 2, mode, mcptools.Breakdown())
	}

	// День 18: режим 24/7. Агент ставит города на фоновый сбор и периодически
	// печатает агрегированную сводку. Токены не тратятся (прямые вызовы тулов).
	if *watchSec > 0 {
		if mcptools == nil {
			log.Fatal("режим -watch требует доступного MCP-сервера")
		}
		runWatch(ctx, mcptools, *watchSec, strings.Split(*track, ","), *interval)
		_ = mem.Save()
		return
	}

	fmt.Println("Накопительный агент: память (3 слоя) + персонализация.")
	fmt.Printf("Активный профиль: %q · профили: %v\n", agent.ProfileID(), store.List())
	fmt.Printf("Память: %s\n", *memDir)
	fmt.Println("Команды:")
	fmt.Println("  профиль (long-term): /profile <id> · /profiles · /whoami")
	fmt.Println("  working:  /task <имя> · /goal <..> · /plan a; b · /current <шаг> · /done <шаг> · /decide k=v")
	fmt.Println("  состояние:/state · /run (прогнать этапы) · /advance (шаг вперёд) · pause")
	fmt.Println("  инварианты:/invariants · /forbid <стоп-слово> · /invariant <правило>")
	fmt.Println("  переходы: /approve-plan · /validate-ok · /goto <state> (контроль gate)")
	fmt.Println("  прочее:   /mem · /reset-task · exit")
	if *confirm {
		fmt.Println("  режим -confirm: перед каждым переходом спрошу y/n/pause")
	}
	if mem.State().valid() && mem.TaskName() != "" {
		fmt.Printf("Возобновление: задача %q на этапе %s.\n", mem.TaskName(), mem.State())
	}

	reader := bufio.NewReader(os.Stdin)
	pipe := NewPipeline(agent, *confirm, reader)
	if *swarmOn {
		pipe.EnableSwarm(NewSwarm(client, model, swarmStageOf(*swarmStage)))
	}
	for {
		fmt.Print("> ")
		line, err := reader.ReadString('\n')
		if err != nil {
			fmt.Println()
			break
		}
		line = strings.TrimSpace(line)
		switch {
		case line == "":
			continue
		case line == "exit":
			_ = mem.Save()
			fmt.Println("Сохранил память. Exiting")
			return
		case line == "/mem":
			fmt.Print(mem.Inspect())
			continue
		case line == "/reset-task":
			mem.ResetTask()
			fmt.Println("рабочая память очищена")
			continue
		case strings.HasPrefix(line, "/track "):
			if mcptools == nil {
				fmt.Println("MCP недоступен")
				continue
			}
			parts := strings.Fields(strings.TrimPrefix(line, "/track "))
			if len(parts) == 0 {
				fmt.Println("использование: /track <город> [интервал_сек]")
				continue
			}
			iv := 30
			if n, err := strconv.Atoi(parts[len(parts)-1]); err == nil && len(parts) > 1 {
				iv = n
				parts = parts[:len(parts)-1]
			}
			out, _ := mcptools.Call(ctx, "track_location", jsonArgs(map[string]any{
				"location": strings.Join(parts, " "), "interval_sec": iv,
			}))
			fmt.Println(out)
			continue
		case line == "/summary" || strings.HasPrefix(line, "/summary "):
			if mcptools == nil {
				fmt.Println("MCP недоступен")
				continue
			}
			loc := strings.TrimSpace(strings.TrimPrefix(line, "/summary"))
			out, _ := mcptools.Call(ctx, "weather_summary", jsonArgs(map[string]any{"location": loc}))
			fmt.Println(out)
			continue
		case strings.HasPrefix(line, "/untrack "):
			if mcptools == nil {
				fmt.Println("MCP недоступен")
				continue
			}
			city := strings.TrimSpace(strings.TrimPrefix(line, "/untrack "))
			out, _ := mcptools.Call(ctx, "untrack_location", jsonArgs(map[string]any{"location": city}))
			fmt.Println(out)
			continue
		case line == "/untrack-all":
			if mcptools == nil {
				fmt.Println("MCP недоступен")
				continue
			}
			listed, _ := mcptools.Call(ctx, "list_tracked", json.RawMessage(`{}`))
			for _, row := range strings.Split(listed, "\n") {
				name := strings.TrimSpace(strings.SplitN(row, ",", 2)[0])
				if name == "" || name == "ничего не отслеживается" {
					continue
				}
				mcptools.Call(ctx, "untrack_location", jsonArgs(map[string]any{"location": name}))
			}
			fmt.Println("всё снято с отслеживания")
			continue
		case strings.HasPrefix(line, "/watch "):
			if mcptools == nil {
				fmt.Println("MCP недоступен")
				continue
			}
			n, err := strconv.Atoi(strings.TrimSpace(strings.TrimPrefix(line, "/watch ")))
			if err != nil || n <= 0 {
				fmt.Println("использование: /watch <сек> (Ctrl-C для выхода из режима)")
				continue
			}
			runWatch(ctx, mcptools, n, nil, 30)
			continue
		case line == "/profiles":
			fmt.Printf("доступно: %v\n", store.List())
			continue
		case line == "/whoami":
			fmt.Printf("активный профиль: %q\n%s\n", agent.ProfileID(), mem.LongDoc())
			continue
		case strings.HasPrefix(line, "/profile "):
			id := strings.TrimSpace(strings.TrimPrefix(line, "/profile "))
			p, err := store.Load(id)
			if err != nil {
				fmt.Printf("профиль %q не найден; доступно: %v\n", id, store.List())
				continue
			}
			agent.SetProfile(p)
			fmt.Printf("профиль переключён на %q\n", id)
			continue
		case line == "/invariants":
			for _, iv := range inv.All() {
				fmt.Printf("  [%s/%s] %s\n", iv.Kind, iv.ID, iv.Text)
			}
			continue
		case strings.HasPrefix(line, "/forbid "):
			word := strings.TrimSpace(strings.TrimPrefix(line, "/forbid "))
			iv := inv.Add("Запрещено пользователем: "+word, []string{word})
			fmt.Printf("добавлен инвариант [%s]: запрет %q\n", iv.ID, word)
			continue
		case strings.HasPrefix(line, "/invariant "):
			rule := strings.TrimSpace(strings.TrimPrefix(line, "/invariant "))
			iv := inv.Add(rule, nil)
			fmt.Printf("добавлен инвариант [%s] (семантический, проверяется LLM): %s\n", iv.ID, rule)
			continue
		case line == "/state":
			fmt.Printf("state=%s — %s | план утверждён=%v, валидация=%v\n",
				mem.State(), expectedAction[mem.State()], mem.PlanApproved(), mem.Validated())
			continue
		case line == "/approve-plan":
			mem.ApprovePlan()
			_ = mem.Save()
			fmt.Println("план утверждён — теперь разрешён переход planning → execution")
			continue
		case line == "/validate-ok":
			mem.MarkValidated()
			_ = mem.Save()
			fmt.Println("валидация отмечена пройденной — разрешён переход validation → done")
			continue
		case strings.HasPrefix(line, "/goto "):
			target := TaskState(strings.TrimSpace(strings.TrimPrefix(line, "/goto ")))
			from := mem.State()
			if err := mem.Goto(target); err != nil {
				fmt.Printf("ПЕРЕХОД ЗАПРЕЩЁН: %s. Остаюсь на %s.\n", err.Error(), from)
			} else {
				fmt.Printf("переход %s → %s выполнен\n", from, target)
				_ = mem.Save()
			}
			continue
		case line == "/advance":
			from := mem.State()
			to, err := mem.Advance()
			if err != nil {
				fmt.Println("переход невозможен:", err.Error())
			} else {
				fmt.Printf("переход %s → %s\n", from, to)
				_ = mem.Save()
			}
			continue
		case line == "/run":
			done, err := pipe.Run(ctx)
			if err != nil {
				log.Printf("pipeline: %s", err.Error())
			} else if done {
				fmt.Println("[pipeline] задача доведена до done.")
			}
			continue
		case strings.HasPrefix(line, "/"):
			handleWorkingCmd(mem, line)
			continue
		}

		reply, err := agent.Ask(ctx, line, FullPolicy())
		if err != nil {
			if ctx.Err() != nil {
				return
			}
			log.Printf("error: %s", err.Error())
			continue
		}
		fmt.Println(reply.Text)
		fmt.Printf("[профиль %q · слои: %s]\n", reply.ProfileID, layersString(reply.UsedLayers))
		_ = mem.Save()
	}
}

func splitCmd(line string) (string, string) {
	f := strings.SplitN(line, " ", 2)
	if len(f) == 1 {
		return f[0], ""
	}
	return f[0], strings.TrimSpace(f[1])
}

func splitKV(s string) (string, string) {
	i := strings.IndexByte(s, '=')
	if i < 0 {
		return s, ""
	}
	return strings.TrimSpace(s[:i]), strings.TrimSpace(s[i+1:])
}

func splitSemicolons(s string) []string {
	var out []string
	for _, p := range strings.Split(s, ";") {
		if t := strings.TrimSpace(p); t != "" {
			out = append(out, t)
		}
	}
	return out
}

// ServerSpec — один MCP-сервер: логическое имя + назначение + команда запуска.
type ServerSpec struct {
	Name    string
	Purpose string // короткое назначение для каталога (ленивый режим)
	Cmd     []string
}

// MCPTools — день 20: подключение к НЕСКОЛЬКИМ MCP-серверам, агрегация их тулов
// и МАРШРУТИЗАЦИЯ вызова по имени тула к серверу-владельцу.
type MCPTools struct {
	tools    []anthropic.ToolUnionParam    // объединённый список для модели (жадный режим)
	route    map[string]*mcp.ClientSession // имя тула -> сессия владельца
	origin   map[string]string             // имя тула -> имя сервера (для вывода)
	byServer map[string][]string           // сервер -> его тулы (имена)

	// для ленивого режима (день 20, усиление):
	toolsByServer map[string][]anthropic.ToolUnionParam // сервер -> его тулы (схемы)
	purpose       map[string]string                     // сервер -> назначение (для каталога)
	serverOrder   []string                              // порядок серверов (детерминированный)
}

// ConnectMCP поднимает все указанные серверы (stdio-сабпроцессы), собирает их тулы
// в общий список и строит таблицу маршрутизации. Возвращает реестр и stop-функцию.
func ConnectMCP(ctx context.Context, servers []ServerSpec) (*MCPTools, func(), error) {
	m := &MCPTools{
		route:         map[string]*mcp.ClientSession{},
		origin:        map[string]string{},
		byServer:      map[string][]string{},
		toolsByServer: map[string][]anthropic.ToolUnionParam{},
		purpose:       map[string]string{},
	}
	var stops []func()
	stopAll := func() {
		for _, s := range stops {
			s()
		}
	}

	for _, spec := range servers {
		m.serverOrder = append(m.serverOrder, spec.Name)
		m.purpose[spec.Name] = spec.Purpose
		client := mcp.NewClient(&mcp.Implementation{Name: "day20-agent", Version: "0.1.0"}, nil)
		cmd := exec.CommandContext(ctx, spec.Cmd[0], spec.Cmd[1:]...)

		// stderr каждого сервера — в свой лог-файл, чтобы не засорять REPL.
		var logFile *os.File
		if f, err := os.Create(filepath.Join(sourceDir(), spec.Name+".log")); err == nil {
			cmd.Stderr = f
			logFile = f
		} else {
			cmd.Stderr = os.Stderr
		}

		session, err := client.Connect(ctx, &mcp.CommandTransport{Command: cmd}, nil)
		if err != nil {
			if logFile != nil {
				_ = logFile.Close()
			}
			stopAll()
			return nil, func() {}, fmt.Errorf("mcp connect %q: %w", spec.Name, err)
		}
		sess := session
		lf := logFile
		stops = append(stops, func() {
			_ = sess.Close()
			if lf != nil {
				_ = lf.Close()
			}
		})

		lt, err := session.ListTools(ctx, nil)
		if err != nil {
			stopAll()
			return nil, func() {}, fmt.Errorf("mcp tools/list %q: %w", spec.Name, err)
		}
		for _, t := range lt.Tools {
			if _, dup := m.route[t.Name]; dup {
				// коллизия имён между серверами — оставляем первого владельца, предупреждаем.
				fmt.Printf("[mcp] предупреждение: тул %q есть на нескольких серверах; беру %q\n", t.Name, m.origin[t.Name])
				continue
			}
			tool := oneTool(t)
			m.tools = append(m.tools, tool)
			m.toolsByServer[spec.Name] = append(m.toolsByServer[spec.Name], tool)
			m.route[t.Name] = session
			m.origin[t.Name] = spec.Name
			m.byServer[spec.Name] = append(m.byServer[spec.Name], t.Name)
		}
	}
	return m, stopAll, nil
}

// CatalogTools — стартовый набор для ЛЕНИВОГО режима: один мета-тул load_tools,
// в описании которого перечислены серверы и их назначение, но БЕЗ полных схем их тулов.
// Это и есть «каталог серверов», с которого начинает модель (экономия токенов).
func (m *MCPTools) CatalogTools() []anthropic.ToolUnionParam {
	var lines []string
	enum := make([]any, 0, len(m.serverOrder))
	for _, s := range m.serverOrder {
		lines = append(lines, fmt.Sprintf("%q — %s (тулов: %d)", s, m.purpose[s], len(m.toolsByServer[s])))
		enum = append(enum, s)
	}
	desc := "Загрузить инструменты одного MCP-сервера ПЕРЕД их использованием. " +
		"Сначала загрузи сервер, подходящий под задачу, затем вызывай его тулы. " +
		"Доступные серверы: " + strings.Join(lines, "; ") + "."
	tp := anthropic.ToolParam{
		Name:        LoadToolsName,
		Description: anthropic.String(desc),
		InputSchema: anthropic.ToolInputSchemaParam{
			Properties: map[string]any{
				"server": map[string]any{"type": "string", "enum": enum, "description": "Имя сервера из каталога"},
			},
			Required: []string{"server"},
		},
	}
	return []anthropic.ToolUnionParam{{OfTool: &tp}}
}

// LoadServer возвращает схемы тулов запрошенного сервера (для подмешивания в запрос)
// и текстовое подтверждение для модели. Вызывается, когда модель дёрнула load_tools.
func (m *MCPTools) LoadServer(input json.RawMessage) ([]anthropic.ToolUnionParam, string) {
	var in struct {
		Server string `json:"server"`
	}
	_ = json.Unmarshal(input, &in)
	tools, ok := m.toolsByServer[in.Server]
	if !ok {
		return nil, fmt.Sprintf("нет сервера %q; доступны: %s", in.Server, strings.Join(m.serverOrder, ", "))
	}
	return tools, fmt.Sprintf("загружены инструменты сервера %q: %s. Теперь можешь их вызывать.",
		in.Server, strings.Join(m.byServer[in.Server], ", "))
}

// appendNewTools добавляет тулы, которых ещё нет (дедуп по имени).
func appendNewTools(existing, added []anthropic.ToolUnionParam) []anthropic.ToolUnionParam {
	have := map[string]bool{}
	for _, t := range existing {
		if t.OfTool != nil {
			have[t.OfTool.Name] = true
		}
	}
	for _, t := range added {
		if t.OfTool != nil && !have[t.OfTool.Name] {
			existing = append(existing, t)
			have[t.OfTool.Name] = true
		}
	}
	return existing
}

// Names — все тулы, отсортированно (для стартового вывода).
func (m *MCPTools) Names() []string {
	out := make([]string, 0, len(m.route))
	for n := range m.route {
		out = append(out, n)
	}
	sort.Strings(out)
	return out
}

// Breakdown — какие тулы с какого сервера (для стартового вывода).
func (m *MCPTools) Breakdown() string {
	servers := make([]string, 0, len(m.byServer))
	for s := range m.byServer {
		servers = append(servers, s)
	}
	sort.Strings(servers)
	var parts []string
	for _, s := range servers {
		tools := append([]string(nil), m.byServer[s]...)
		sort.Strings(tools)
		parts = append(parts, fmt.Sprintf("%s(%d): %s", s, len(tools), strings.Join(tools, ", ")))
	}
	return strings.Join(parts, " | ")
}

// Call МАРШРУТИЗИРУЕТ вызов к серверу-владельцу тула.
func (m *MCPTools) Call(ctx context.Context, name string, input json.RawMessage) (string, bool) {
	session, ok := m.route[name]
	if !ok {
		return "неизвестный инструмент: " + name, true
	}
	var args map[string]any
	if len(input) > 0 {
		if err := json.Unmarshal(input, &args); err != nil {
			return "не разобрал аргументы инструмента: " + err.Error(), true
		}
	}
	res, err := session.CallTool(ctx, &mcp.CallToolParams{Name: name, Arguments: args})
	if err != nil {
		return fmt.Sprintf("ошибка вызова %s: %v", name, err), true
	}
	return mcpResultText(res), res.IsError
}

// oneTool конвертирует один MCP-инструмент в формат tools Anthropic.
func oneTool(t *mcp.Tool) anthropic.ToolUnionParam {
	props, required := splitSchema(t.InputSchema)
	tp := anthropic.ToolParam{
		Name:        t.Name,
		Description: anthropic.String(t.Description),
		InputSchema: anthropic.ToolInputSchemaParam{Properties: props, Required: required},
	}
	return anthropic.ToolUnionParam{OfTool: &tp}
}

// splitSchema достаёт properties и required из JSON-схемы MCP-инструмента.
// Properties ВСЕГДА непустой объект: иначе ToolInputSchemaParam считается "нулевым"
// и из-за omitzero выпадает из запроса целиком (API → input_schema: Field required).
func splitSchema(schema any) (props any, required []string) {
	var m map[string]any
	switch v := schema.(type) {
	case map[string]any:
		m = v
	case json.RawMessage:
		_ = json.Unmarshal(v, &m)
	case []byte:
		_ = json.Unmarshal(v, &m)
	case string:
		_ = json.Unmarshal([]byte(v), &m)
	}
	if m == nil {
		return map[string]any{}, nil
	}
	if p, ok := m["properties"].(map[string]any); ok {
		props = p
	} else {
		props = map[string]any{}
	}
	if rs, ok := m["required"].([]any); ok {
		for _, r := range rs {
			if s, ok := r.(string); ok {
				required = append(required, s)
			}
		}
	}
	return props, required
}

// mcpResultText склеивает текстовые блоки результата MCP-инструмента.
func mcpResultText(res *mcp.CallToolResult) string {
	var b strings.Builder
	for _, c := range res.Content {
		if tc, ok := c.(*mcp.TextContent); ok {
			b.WriteString(tc.Text)
		}
	}
	return b.String()
}

const (
	ShortTerm Layer = iota // краткосрочная: текущий диалог (сообщения чата)
	Working                // рабочая: TaskContext — данные задачи через сессии
	LongTerm               // долговременная: профиль/решения/знания (.md)
)

func (l Layer) String() string {
	switch l {
	case ShortTerm:
		return "short-term (диалог)"
	case Working:
		return "working (TaskContext)"
	case LongTerm:
		return "long-term (профиль)"
	default:
		return "unknown"
	}
}

func (w WorkingMem) empty() bool {
	return w.Task == "" && w.Current == "" && len(w.Plan) == 0 &&
		len(w.Done) == 0 && len(w.Facts) == 0
}

// Memory держит ТРИ слоя РАЗДЕЛЬНО, с разным хранилищем:
//
//	short-term → сообщения чата   (short-term.json)
//	working    → TaskContext      (working.json)
//	long-term  → активный профиль  (из ProfileStore)
type Memory struct {
	dir string

	shortTerm []storedMessage // краткосрочная: диалог
	working   WorkingMem      // рабочая: TaskContext
	longDoc   string          // долговременная: markdown-документ
}

func NewMemory(dir string) *Memory {
	return &Memory{dir: dir, working: WorkingMem{Facts: map[string]string{}}}
}

// Dialog → краткосрочная (диалог). Это делает агент сам в Ask.
func (m *Memory) Dialog(role, content string) {
	m.shortTerm = append(m.shortTerm, storedMessage{Role: role, Content: content})
}

// --- рабочая (TaskContext) ---
func (m *Memory) SetTask(name, goal string) {
	m.working.Task, m.working.Goal = name, goal
	if !m.working.State.valid() {
		m.working.State = StatePlanning
	}
}

func (m *Memory) MarkDone(step string) {
	m.working.Done = append(m.working.Done, step)
	out := m.working.Plan[:0]
	for _, s := range m.working.Plan {
		if s != step {
			out = append(out, s)
		}
	}
	m.working.Plan = out
}

func (m *Memory) SetExecArtifact(text, stop string) {
	m.working.ExecText, m.working.ExecStop = text, stop
}

// gateFor возвращает условие, без которого переход from→to запрещён ("" если условий нет).
func (m *Memory) gateError(from, to TaskState) error {
	if from == StatePlanning && to == StateExecution && !m.working.PlanApproved {
		return fmt.Errorf("нельзя в execution: план не утверждён (нужно /approve-plan)")
	}
	if from == StateValidation && to == StateDone && !m.working.Validated {
		return fmt.Errorf("нельзя в done: валидация не пройдена (нужно /validate-ok)")
	}
	return nil
}

// Advance — детерминированный переход на следующий этап (с контролем в коде).
func (m *Memory) Advance() (TaskState, error) {
	to, ok := nextState(m.working.State)
	if !ok {
		return m.working.State, fmt.Errorf("задача уже в состоянии %s — двигаться некуда", m.working.State)
	}
	if err := transition(m.working.State, to); err != nil {
		return m.working.State, err
	}
	if err := m.gateError(m.working.State, to); err != nil {
		return m.working.State, err
	}
	m.working.State = to
	return to, nil
}

// Goto — явный переход на конкретный этап (тоже под контролем transitions).
func (m *Memory) Goto(to TaskState) error {
	if !to.valid() {
		return fmt.Errorf("неизвестное состояние %q", to)
	}
	if err := transition(m.working.State, to); err != nil {
		return err
	}
	if err := m.gateError(m.working.State, to); err != nil {
		return err
	}
	m.working.State = to
	return nil
}

// ResetTask очищает рабочую память (задача завершена), не трогая остальное.
func (m *Memory) ResetTask() {
	m.working = WorkingMem{Facts: map[string]string{}, State: StatePlanning}
}

// Policy — какие слои попадут в запрос. Под задачу слои можно выключать.
type Policy struct {
	Profile    bool // долговременная (активный профиль)
	Working    bool // рабочая (TaskContext)
	ShortTermN int  // сколько последних реплик диалога взять (0 — ни одной)
}

// Build собирает system-блоки и сообщения из ВЫБРАННЫХ слоёв.
// long-term и working → System; короткий диалог → messages.
func (m *Memory) Build(query string, p Policy) (system []anthropic.TextBlockParam, msgs []anthropic.MessageParam, used []Layer) {
	if p.Profile && strings.TrimSpace(m.longDoc) != "" {
		system = append(system, anthropic.TextBlockParam{Text: "[ДОЛГОВРЕМЕННАЯ ПАМЯТЬ — профиль]\n" + m.longDoc})
		used = append(used, LongTerm)
	}
	if p.Working && !m.working.empty() {
		system = append(system, anthropic.TextBlockParam{Text: "[РАБОЧАЯ ПАМЯТЬ — TaskContext]\n" + m.renderWorking()})
		if m.working.State.valid() {
			system = append(system, anthropic.TextBlockParam{Text: fmt.Sprintf(
				"[ЭТАП ЗАДАЧИ]\nТекущий state: %s.\nНа этом этапе: %s.\nРаботай строго в рамках этого этапа, не перепрыгивай вперёд.",
				m.working.State, expectedAction[m.working.State])})
		}
		used = append(used, Working)
	}

	hist := m.shortTerm
	if p.ShortTermN <= 0 {
		hist = nil
	} else if len(hist) > p.ShortTermN {
		hist = hist[len(hist)-p.ShortTermN:]
	}
	if len(hist) > 0 {
		used = append(used, ShortTerm)
	}
	for _, msg := range hist {
		block := anthropic.NewTextBlock(msg.Content)
		if msg.Role == roleAssistant {
			msgs = append(msgs, anthropic.NewAssistantMessage(block))
			continue
		}
		msgs = append(msgs, anthropic.NewUserMessage(block))
	}
	msgs = append(msgs, anthropic.NewUserMessage(anthropic.NewTextBlock(query)))
	return system, msgs, used
}

func (m *Memory) renderWorking() string {
	var b strings.Builder
	if m.working.Task != "" {
		fmt.Fprintf(&b, "Задача: %s\n", m.working.Task)
	}
	if m.working.Goal != "" {
		fmt.Fprintf(&b, "Цель: %s\n", m.working.Goal)
	}
	if m.working.State != "" {
		fmt.Fprintf(&b, "Этап (state): %s — %s\n", m.working.State, expectedAction[m.working.State])
		fmt.Fprintf(&b, "Gate: план утверждён=%v, валидация пройдена=%v\n", m.working.PlanApproved, m.working.Validated)
	}
	if m.working.Current != "" {
		fmt.Fprintf(&b, "Текущий шаг: %s\n", m.working.Current)
	}
	if len(m.working.Done) > 0 {
		fmt.Fprintf(&b, "Сделано: %s\n", strings.Join(m.working.Done, "; "))
	}
	if len(m.working.Plan) > 0 {
		fmt.Fprintf(&b, "Осталось: %s\n", strings.Join(m.working.Plan, "; "))
	}
	if len(m.working.Facts) > 0 {
		b.WriteString("Решения:\n")
		b.WriteString(renderKV(m.working.Facts))
	}
	return b.String()
}

func renderKV(m map[string]string) string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var b strings.Builder
	for _, k := range keys {
		fmt.Fprintf(&b, "- %s: %s\n", k, m[k])
	}
	return b.String()
}

func (m *Memory) Inspect() string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s — %d сообщений\n", ShortTerm, len(m.shortTerm))
	for _, msg := range m.shortTerm {
		fmt.Fprintf(&b, "    %s: %s\n", msg.Role, oneLine(msg.Content, 70))
	}
	fmt.Fprintf(&b, "%s — задача %q\n", Working, m.working.Task)
	if s := strings.TrimRight(m.renderWorking(), "\n"); s != "" {
		for _, line := range strings.Split(s, "\n") {
			fmt.Fprintf(&b, "    %s\n", line)
		}
	}
	fmt.Fprintf(&b, "%s — %d символов (активный профиль)\n", LongTerm, len(m.longDoc))
	if s := strings.TrimRight(m.longDoc, "\n"); s != "" {
		for _, line := range strings.Split(s, "\n") {
			fmt.Fprintf(&b, "    %s\n", line)
		}
	}
	return b.String()
}

// Save сохраняет слои, которыми управляет агент: диалог и TaskContext.
// Долговременный слой здесь = активный профиль, его персистит ProfileStore.
func (m *Memory) Save() error {
	if m.dir == "" {
		return nil
	}
	if err := os.MkdirAll(m.dir, 0o755); err != nil {
		return err
	}
	if err := writeJSON(filepath.Join(m.dir, "short-term.json"), m.shortTerm); err != nil {
		return err
	}
	return writeJSON(filepath.Join(m.dir, "working.json"), m.working)
}

func LoadMemory(dir string) (*Memory, error) {
	m := NewMemory(dir)
	_ = readJSON(filepath.Join(dir, "short-term.json"), &m.shortTerm)
	_ = readJSON(filepath.Join(dir, "working.json"), &m.working)
	if m.working.Facts == nil {
		m.working.Facts = map[string]string{}
	}
	return m, nil
}

func writeJSON(path string, v any) error {
	data, err := json.MarshalIndent(v, "", "  ")
	if err != nil {
		return err
	}
	return writeFile(path, string(data))
}

func writeFile(path, content string) error {
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, []byte(content), 0o644); err != nil {
		return err
	}
	return os.Rename(tmp, path)
}

func readJSON(path string, v any) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, v)
}

func oneLine(s string, max int) string {
	s = strings.Join(strings.Fields(s), " ")
	r := []rune(s)
	if len(r) <= max {
		return s
	}
	return string(r[:max-1]) + "…"
}

// День 20. Второй MCP-сервер ДРУГОЙ природы — файловое хранилище ("notes").
// Не знает ничего про погоду: принимает текст и работает с файлами в каталоге notes/.
// Демонстрирует оркестрацию тулов с РАЗНЫХ серверов: данные приходят с weatherserver,
// сохранение/чтение — здесь. Транспорт stdio (отдельный сабпроцесс агента).
func main() {
	s := mcp.NewServer(&mcp.Implementation{Name: "notes-mcp", Version: "0.1.0"}, nil)

	// save_to_file — сохранить переданный текст в файл.
	s.AddTool(&mcp.Tool{
		Name:        "save_to_file",
		Description: "Сохранить текст в файл в каталоге notes/. Возвращает путь к файлу.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"filename":{"type":"string","description":"Имя файла, напр. 'trip.txt'"},
				"content":{"type":"string","description":"Содержимое для сохранения"}
			},
			"required":["filename","content"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Filename string `json:"filename"`
			Content  string `json:"content"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errText(err), nil
		}
		path, err := writeNote(in.Filename, in.Content)
		if err != nil {
			return errText(err), nil
		}
		return okText(fmt.Sprintf("сохранено: %s (%d байт)", path, len(in.Content))), nil
	})

	// read_file — прочитать ранее сохранённый файл.
	s.AddTool(&mcp.Tool{
		Name:        "read_file",
		Description: "Прочитать файл из каталога notes/ и вернуть его содержимое.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{"filename":{"type":"string","description":"Имя файла"}},
			"required":["filename"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Filename string `json:"filename"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errText(err), nil
		}
		data, err := readNote(in.Filename)
		if err != nil {
			return errText(err), nil
		}
		return okText(data), nil
	})

	// list_files — список сохранённых файлов.
	s.AddTool(&mcp.Tool{
		Name:        "list_files",
		Description: "Список файлов в каталоге notes/.",
		InputSchema: json.RawMessage(`{"type":"object"}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		names, err := listNotes()
		if err != nil {
			return errText(err), nil
		}
		if len(names) == 0 {
			return okText("файлов пока нет"), nil
		}
		return okText(strings.Join(names, "\n")), nil
	})

	// delete_file — удалить файл.
	s.AddTool(&mcp.Tool{
		Name:        "delete_file",
		Description: "Удалить файл из каталога notes/.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{"filename":{"type":"string","description":"Имя файла"}},
			"required":["filename"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Filename string `json:"filename"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errText(err), nil
		}
		if err := deleteNote(in.Filename); err != nil {
			return errText(err), nil
		}
		return okText("удалено: " + in.Filename), nil
	})

	if err := s.Run(context.Background(), &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}
}

func notesDir() (string, error) {
	dir := filepath.Join(sourceDir(), "notes")
	return dir, os.MkdirAll(dir, 0o755)
}

// safeName очищает имя файла от путей (защита от traversal).
func safeName(filename string) (string, error) {
	name := filepath.Base(strings.TrimSpace(filename))
	if name == "" || name == "." || name == ".." || strings.ContainsAny(name, `/\`) {
		return "", fmt.Errorf("недопустимое имя файла: %q", filename)
	}
	return name, nil
}

func writeNote(filename, content string) (string, error) {
	name, err := safeName(filename)
	if err != nil {
		return "", err
	}
	dir, err := notesDir()
	if err != nil {
		return "", err
	}
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return "", err
	}
	return path, nil
}

func readNote(filename string) (string, error) {
	name, err := safeName(filename)
	if err != nil {
		return "", err
	}
	dir, err := notesDir()
	if err != nil {
		return "", err
	}
	data, err := os.ReadFile(filepath.Join(dir, name))
	if err != nil {
		return "", fmt.Errorf("не прочитать %s: %w", name, err)
	}
	return string(data), nil
}

func listNotes() ([]string, error) {
	dir, err := notesDir()
	if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var names []string
	for _, e := range entries {
		if !e.IsDir() {
			names = append(names, e.Name())
		}
	}
	sort.Strings(names)
	return names, nil
}

func deleteNote(filename string) error {
	name, err := safeName(filename)
	if err != nil {
		return err
	}
	dir, err := notesDir()
	if err != nil {
		return err
	}
	return os.Remove(filepath.Join(dir, name))
}

func sourceDir() string {
	if _, file, _, ok := runtime.Caller(0); ok {
		return filepath.Dir(file)
	}
	return "."
}

func okText(s string) *mcp.CallToolResult {
	return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: s}}}
}

func errText(err error) *mcp.CallToolResult {
	return &mcp.CallToolResult{IsError: true, Content: []mcp.Content{&mcp.TextContent{Text: "ошибка: " + err.Error()}}}
}

// Pipeline прогоняет задачу по этапам planning → execution → validation → done
// ДЕТЕРМИНИРОВАННО (переходы в коде). Опционально ставит паузу и спрашивает юзера
// перед каждым переходом (confirm-режим).
type Pipeline struct {
	agent           *Agent
	confirm         bool
	in              *bufio.Reader // источник подтверждений (stdin в чате)
	swarm           *Swarm        // рой ревьюеров на validation (опц.)
	lastPlan        string        // артефакт planning (для роя)
	lastExec        string        // артефакт execution (для роя)
	userQuery       string        // исходный запрос (для оркестратора)
	reworkLeft      int           // сколько кругов доработки validation→execution ещё разрешено
	reworkExhausted bool          // лимит доработки исчерпан → пауза, ждём решение человека
	lastStop        string        // stop_reason последнего ответа execution (для проверки обрыва)
}

func NewPipeline(agent *Agent, confirm bool, in *bufio.Reader) *Pipeline {
	return &Pipeline{agent: agent, confirm: confirm, in: in, reworkLeft: defaultReworkRounds}
}

// stageQuery — что просим у модели на каждом этапе для данной задачи.
func stageQuery(state TaskState, task string) string {
	switch state {
	case StatePlanning:
		return fmt.Sprintf("Задача: %s. Составь короткий план (3–5 шагов). Только план, без кода.", task)
	case StateExecution:
		return "Выполни план по шагам и дай результат (код/артефакт)."
	case StateValidation:
		return "Проверь результат на соответствие плану. Кратко: что ок, что нет."
	default:
		return ""
	}
}

// Run прогоняет автомат от текущего state до done.
// Возвращает true, если дошли до done; false — если поставлено на паузу.
func (p *Pipeline) Run(ctx context.Context) (bool, error) {
	mem := p.agent.Memory()
	for {
		state := mem.State()
		if state == StateDone {
			fmt.Println("[pipeline] задача в состоянии done — завершено.")
			return true, nil
		}

		q := stageQuery(state, mem.TaskName())
		if p.userQuery == "" {
			p.userQuery = mem.TaskName()
		}
		fmt.Printf("\n[этап %s] %s\n", state, expectedAction[state])
		fmt.Printf("[запрос] %s\n", q)
		reply, err := p.agent.Ask(ctx, q, FullPolicy())
		if err != nil {
			return false, err
		}
		fmt.Println(reply.Text)

		// запоминаем артефакты этапов и выставляем gate-флаги
		switch state {
		case StatePlanning:
			p.lastPlan = reply.Text
			mem.SetPlanText(reply.Text)
			if p.swarm != nil && p.swarm.Stage() == StatePlanning {
				if err := p.runSwarmPlanning(ctx); err != nil {
					return false, err
				}
			}
			mem.ApprovePlan() // план утверждён (после роя, если он был)
		case StateExecution:
			p.lastExec = reply.Text
			p.lastStop = reply.StopReason
			mem.SetExecArtifact(reply.Text, reply.StopReason)
		case StateValidation:
			if p.swarm != nil && p.swarm.Stage() == StateValidation {
				if err := p.runSwarm(ctx); err != nil {
					return false, err
				}
			} else {
				mem.MarkValidated()
			}
		}

		// лимит доработки исчерпан → пауза (вариант A): сохраняем состояние и выходим
		if p.reworkExhausted {
			fmt.Println("[pipeline] пауза: доработка не сходится. Состояние сохранено; нужно решение человека.")
			_ = mem.Save()
			return false, nil
		}

		to, ok := nextState(state)
		if !ok {
			return true, nil
		}

		// пауза + подтверждение перед детерминированным переходом
		if p.confirm {
			ok, paused := p.askConfirm(state, to)
			if paused {
				fmt.Printf("[pipeline] пауза на этапе %s. Состояние сохранено; продолжить позже.\n", state)
				_ = mem.Save()
				return false, nil
			}
			if !ok {
				// не подтвердил переход вперёд: на validation можно вернуть в execution
				if state == StateValidation {
					if err := mem.Goto(StateExecution); err == nil {
						fmt.Println("[pipeline] возвращаюсь в execution для доработки.")
						_ = mem.Save()
						continue
					}
				}
				fmt.Println("[pipeline] переход отклонён; остаюсь на текущем этапе (пауза).")
				_ = mem.Save()
				return false, nil
			}
		}

		newState, err := mem.Advance() // детерминированный переход с контролем в коде
		if err != nil {
			return false, err
		}
		fmt.Printf("[переход] %s → %s\n", state, newState)
		_ = mem.Save()
	}
}

// runSwarm запускает рой ревьюеров + оркестратора на этапе validation.
// Если оркестратор не пропустил — gate Validated НЕ ставится (в done не уйдём).
func (p *Pipeline) runSwarm(ctx context.Context) error {
	// после resume (пауза → новый процесс) поля пайплайна пусты — берём артефакты из памяти
	mem := p.agent.Memory()
	if p.lastExec == "" {
		p.lastExec, p.lastStop = mem.ExecText(), mem.ExecStop()
	}
	if p.lastPlan == "" {
		p.lastPlan = mem.PlanText()
	}
	// Лёгкий детерминированный гейт ПЕРЕД роем: ловит ТОЛЬКО объективный обрыв/пустоту
	// (stop_reason=max_tokens или незакрытый блок кода). Отсутствие кода — НЕ ошибка:
	// бывают задачи без кода (план/анализ/доки), их по сути проверяет рой.
	if chk := CheckResult(p.lastExec, p.lastStop); !chk.OK {
		fmt.Printf("\n[проверка результата] неполный результат — %s\n", chk.Reason)
		if p.reworkLeft <= 0 {
			p.reworkExhausted = true
			fmt.Printf("  не сошлось за %d круга доработки — СТОП.\n", defaultReworkRounds)
			fmt.Println("  [пауза] результат неполный; решение человека (дореализовать / сузить / закрыть).")
			return nil
		}
		p.reworkLeft--
		fmt.Printf("  рой не запускаю (результат неполный) → возврат в execution (осталось кругов: %d).\n", p.reworkLeft)
		_ = p.agent.Memory().Goto(StateExecution)
		return nil
	}
	fmt.Println("\n[проверка результата] OK — результат полный, передаю рою на содержательную проверку.")
	fmt.Println("[рой] запускаю ревьюеров на validation…")
	fmt.Printf("  [вход роя] план: %s\n", oneLine(p.lastPlan, 160))
	fmt.Printf("  [вход роя] результат: %s\n", oneLine(p.lastExec, 160))
	reviews, err := p.swarm.Review(ctx, p.lastPlan, p.lastExec)
	if err != nil {
		return err
	}
	for _, r := range reviews {
		fmt.Printf("  [ревьюер: %s] %s — %s\n", r.Name, r.Verdict, r.Notes)
	}
	fmt.Printf("  [вход оркестратора] запрос юзера: %q + мнения %d ревьюеров\n", p.userQuery, len(reviews))
	passed, summary, err := p.swarm.Orchestrate(ctx, p.userQuery, reviews)
	if err != nil {
		return err
	}
	fmt.Printf("  [оркестратор] PASS=%v — %s\n", passed, summary)
	if passed {
		p.agent.Memory().MarkValidated()
		return nil
	}
	// не прошло: тратим круг доработки; если круги исчерпаны — пауза, а не бесконечный цикл
	if p.reworkLeft <= 0 {
		p.reworkExhausted = true
		fmt.Printf("  [рой] замечания не устранены за %d круга доработки — СТОП.\n", defaultReworkRounds)
		fmt.Println("  [пауза] доработка не сходится; нужно решение человека (дореализовать / сузить план / закрыть).")
		return nil
	}
	p.reworkLeft--
	fmt.Printf("  [рой] есть замечания → возврат в execution на доработку (осталось кругов: %d).\n", p.reworkLeft)
	_ = p.agent.Memory().Goto(StateExecution)
	return nil
}

// runSwarmPlanning запускает рой на этапе planning: ревьюеры оценивают ПЛАН,
// оркестратор сводит мнения (план принимается/дорабатывается перед execution).
func (p *Pipeline) runSwarmPlanning(ctx context.Context) error {
	fmt.Println("\n[рой] запускаю планировщиков-ревьюеров на planning…")
	fmt.Printf("  [вход роя] план: %s\n", oneLine(p.lastPlan, 160))
	reviews, err := p.swarm.Review(ctx, p.lastPlan, "")
	if err != nil {
		return err
	}
	for _, r := range reviews {
		fmt.Printf("  [ревьюер: %s] %s — %s\n", r.Name, r.Verdict, r.Notes)
	}
	fmt.Printf("  [вход оркестратора] запрос юзера: %q + мнения %d ревьюеров\n", p.userQuery, len(reviews))
	passed, summary, err := p.swarm.Orchestrate(ctx, p.userQuery, reviews)
	if err != nil {
		return err
	}
	fmt.Printf("  [оркестратор] план принят=%v — %s\n", passed, summary)
	return nil
}

// askConfirm спрашивает юзера: продолжить переход, нет, или пауза.
// returns (proceed, paused).
func (p *Pipeline) askConfirm(from, to TaskState) (bool, bool) {
	if p.in == nil {
		return true, false
	}
	fmt.Printf("[confirm] этап %s завершён. Перейти к %s? [y = да / n = доработать / pause]: ", from, to)
	line, err := p.in.ReadString('\n')
	if err != nil {
		return false, true
	}
	switch strings.ToLower(strings.TrimSpace(line)) {
	case "y", "yes", "да", "":
		return true, false
	case "pause", "p", "пауза":
		return false, true
	default:
		return false, false
	}
}

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Profile — профиль пользователя: предпочтения (стиль, формат, ограничения).
// Хранится как редактируемый markdown (как long-term-слой из дня 11), но теперь
// профилей МНОГО и между ними можно переключаться.
type Profile struct {
	ID  string
	Doc string // markdown с предпочтениями
}

// ProfileStore хранит профили РАЗДЕЛЬНО: каждый — свой файл <id>.md в каталоге.
// Плюс есть встроенные демо-профили (none / junior / senior-go).
type ProfileStore struct {
	dir     string
	builtin map[string]string
}

func NewProfileStore(dir string) *ProfileStore {
	return &ProfileStore{dir: dir, builtin: builtinProfiles()}
}

// Load берёт профиль по id: сначала файл <id>.md, иначе встроенный.
func (s *ProfileStore) Load(id string) (Profile, error) {
	if s.dir != "" {
		if data, err := os.ReadFile(filepath.Join(s.dir, id+".md")); err == nil {
			return Profile{ID: id, Doc: string(data)}, nil
		}
	}
	if doc, ok := s.builtin[id]; ok {
		return Profile{ID: id, Doc: doc}, nil
	}
	return Profile{ID: id}, os.ErrNotExist
}

// List — доступные id (встроенные + файлы в каталоге), без дублей.
func (s *ProfileStore) List() []string {
	seen := map[string]bool{}
	var ids []string
	for id := range s.builtin {
		if !seen[id] {
			seen[id] = true
			ids = append(ids, id)
		}
	}
	if s.dir != "" {
		entries, _ := os.ReadDir(s.dir)
		for _, e := range entries {
			if strings.HasSuffix(e.Name(), ".md") {
				id := strings.TrimSuffix(e.Name(), ".md")
				if !seen[id] {
					seen[id] = true
					ids = append(ids, id)
				}
			}
		}
	}
	sort.Strings(ids)
	return ids
}

// Save пишет профиль в <id>.md (пользователь может потом править руками).
func (s *ProfileStore) Save(p Profile) error {
	if s.dir == "" {
		return nil
	}
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(s.dir, p.ID+".md"), []byte(p.Doc), 0o644)
}

