// Reviewer — один проверяющий агент роя (своя «роль»/угол зрения и system prompt).
type Reviewer struct {
	Name   string
	System string
}

// validationReviewers — рой проверяющих для этапа validation: смотрят с разных сторон.
func validationReviewers() []Reviewer {
	return []Reviewer{
		{Name: "корректность", System: "Ты ревьюер-критик. Проверь РЕЗУЛЬТАТ на соответствие ПЛАНУ: что не сделано, что расходится. Кратко, по пунктам."},
		{Name: "инварианты", System: "Ты ревьюер по ограничениям. Проверь, не нарушает ли результат инварианты (стек, отсутствие тяжёлых зависимостей, секреты). Кратко."},
		{Name: "качество", System: "Ты ревьюер по качеству Go. Оцени идиоматичность, обработку ошибок, тестируемость. Кратко, без переписывания."},
	}
}

// planningReviewers — рой на этапе planning/research: смотрят план с разных сторон
// (пример лектора «этап исследования 5 агентами с разных сторон»).
func planningReviewers() []Reviewer {
	return []Reviewer{
		{Name: "архитектура", System: "Ты архитектор. Оцени ПЛАН с точки зрения структуры и границ модулей. Что упущено? Кратко."},
		{Name: "риски", System: "Ты ревьюер рисков. Найди в ПЛАНЕ слабые места, неучтённые edge-cases, переусложнение. Кратко."},
		{Name: "стек/инварианты", System: "Ты ревьюер ограничений. Проверь, согласуется ли ПЛАН со стеком и инвариантами (только Go, без тяжёлых зависимостей). Кратко."},
	}
}

// ReviewResult — мнение одного ревьюера.
type ReviewResult struct {
	Name    string
	Verdict string // OK | ISSUES
	Notes   string
}

// Swarm — рой ревьюеров + оркестратор, сводящий мнения в одно решение.
type Swarm struct {
	client    anthropic.Client
	model     anthropic.Model
	stage     TaskState
	reviewers []Reviewer
}

// NewSwarm создаёт рой для конкретного этапа (planning или validation).
func NewSwarm(client anthropic.Client, model anthropic.Model, stage TaskState) *Swarm {
	rv := validationReviewers()
	if stage == StatePlanning {
		rv = planningReviewers()
	}
	return &Swarm{client: client, model: model, stage: stage, reviewers: rv}
}

// Review запускает каждого ревьюера по (план, результат) — отдельный агент-инстанс.
func (s *Swarm) Review(ctx context.Context, plan, result string) ([]ReviewResult, error) {
	var out []ReviewResult
	for _, r := range s.reviewers {
		var user string
		if s.stage == StatePlanning {
			user = "[ПЛАН]\n" + plan +
				"\n\nОтветь строго:\nVERDICT: OK|ISSUES\nNOTES: <1–2 предложения>"
		} else {
			user = "[ПЛАН]\n" + plan + "\n\n[РЕЗУЛЬТАТ]\n" + result +
				"\n\nОтветь строго:\nVERDICT: OK|ISSUES\nNOTES: <1–2 предложения>"
		}
		msg, err := s.client.Messages.New(ctx, anthropic.MessageNewParams{
			Model: s.model, MaxTokens: 250,
			System:   []anthropic.TextBlockParam{{Text: r.System}},
			Messages: []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock(user))},
		})
		if err != nil {
			return nil, fmt.Errorf("reviewer %s: %w", r.Name, err)
		}
		v, n := parseReview(collectText(msg))
		out = append(out, ReviewResult{Name: r.Name, Verdict: v, Notes: n})
	}
	return out, nil
}

// Orchestrate сводит мнения ревьюеров: если хоть один ISSUES — задача не проходит,
// оркестратор знает исходный запрос и принимает сводное решение.
func (s *Swarm) Orchestrate(ctx context.Context, userQuery string, reviews []ReviewResult) (passed bool, summary string, err error) {
	var b strings.Builder
	issues := 0
	for _, r := range reviews {
		fmt.Fprintf(&b, "- [%s] %s: %s\n", r.Name, r.Verdict, r.Notes)
		if strings.ToUpper(r.Verdict) == "ISSUES" {
			issues++
		}
	}
	sys := "Ты агент-оркестратор. Знаешь запрос пользователя и мнения ревьюеров. " +
		"Прими сводное решение: если есть существенные замечания — PASS: NO. " +
		"Ответь строго:\nPASS: YES|NO\nSUMMARY: <1–2 предложения сводного решения>"
	user := "[ЗАПРОС ПОЛЬЗОВАТЕЛЯ]\n" + userQuery + "\n\n[МНЕНИЯ РЕВЬЮЕРОВ]\n" + b.String()
	msg, err := s.client.Messages.New(ctx, anthropic.MessageNewParams{
		Model: s.model, MaxTokens: 250,
		System:   []anthropic.TextBlockParam{{Text: sys}},
		Messages: []anthropic.MessageParam{anthropic.NewUserMessage(anthropic.NewTextBlock(user))},
	})
	if err != nil {
		return false, "", fmt.Errorf("orchestrator: %w", err)
	}
	pass, sum := parsePass(collectText(msg))
	// оркестратор имеет финальное слово, но подстрахуемся: при ISSUES без явного YES — NO
	if issues > 0 && pass {
		// доверяем оркестратору, он видит запрос; оставляем его решение
	}
	return pass, sum, nil
}

func parseReview(s string) (verdict, notes string) {
	verdict = "OK"
	for _, line := range strings.Split(s, "\n") {
		l := strings.TrimSpace(line)
		up := strings.ToUpper(l)
		if strings.HasPrefix(up, "VERDICT:") {
			if strings.Contains(up, "ISSUES") {
				verdict = "ISSUES"
			} else {
				verdict = "OK"
			}
		}
		if strings.HasPrefix(up, "NOTES:") {
			notes = strings.TrimSpace(l[len("NOTES:"):])
		}
	}
	return verdict, notes
}

func parsePass(s string) (pass bool, summary string) {
	for _, line := range strings.Split(s, "\n") {
		l := strings.TrimSpace(line)
		up := strings.ToUpper(l)
		if strings.HasPrefix(up, "PASS:") {
			pass = strings.Contains(up, "YES")
		}
		if strings.HasPrefix(up, "SUMMARY:") {
			summary = strings.TrimSpace(l[len("SUMMARY:"):])
		}
	}
	return pass, summary
}

const (
	opusInPerM   = 5.0
	opusOutPerM  = 25.0
	haikuInPerM  = 1.0
	haikuOutPerM = 5.0
)

func priceFor(model anthropic.Model) (inPerM, outPerM float64) {
	if containsFold(string(model), "haiku") {
		return haikuInPerM, haikuOutPerM
	}
	return opusInPerM, opusOutPerM
}

func costFor(model anthropic.Model, input, output int64) float64 {
	in, out := priceFor(model)
	return float64(input)/1e6*in + float64(output)/1e6*out
}

func containsFold(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if equalFold(s[i:i+len(sub)], sub) {
			return true
		}
	}
	return false
}

func equalFold(a, b string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		ca, cb := a[i], b[i]
		if 'A' <= ca && ca <= 'Z' {
			ca += 'a' - 'A'
		}
		if 'A' <= cb && cb <= 'Z' {
			cb += 'a' - 'A'
		}
		if ca != cb {
			return false
		}
	}
	return true
}

const (
	roleUser      = "user"
	roleAssistant = "assistant"
)

type storedMessage struct {
	Role    string `json:"role"`
	Content string `json:"content"`
}

// runWatch — день 18: «агент 24/7». Ставит города на фоновый сбор (track_location),
// затем по своему тикеру периодически дёргает weather_summary и печатает агрегат.
// Это планировщик на стороне агента; MCP-сервер пассивен (как в каноне из чата).
// Прямые вызовы тулов — без траты токенов LLM.
func runWatch(ctx context.Context, m *MCPTools, watchSec int, locations []string, intervalSec int) {
	// 1) поставить города на фоновый сбор
	for _, loc := range locations {
		loc = strings.TrimSpace(loc)
		if loc == "" {
			continue
		}
		out, _ := m.Call(ctx, "track_location", jsonArgs(map[string]any{
			"location": loc, "interval_sec": intervalSec,
		}))
		fmt.Printf("[watch] %s\n", out)
	}

	// 2) 24/7-цикл: периодическая сводка
	fmt.Printf("[watch] агент работает 24/7: сводка каждые %d с (Ctrl-C — выход)\n", watchSec)
	ticker := time.NewTicker(time.Duration(watchSec) * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			fmt.Println("\n[watch] остановлено, память сохранена")
			return
		case <-ticker.C:
			out, _ := m.Call(ctx, "weather_summary", json.RawMessage(`{}`))
			fmt.Printf("\n[сводка %s]\n%s\n", time.Now().Format("15:04:05"), out)
		}
	}
}

// jsonArgs — компактная сборка JSON-аргументов для вызова MCP-тула.
func jsonArgs(m map[string]any) json.RawMessage {
	b, err := json.Marshal(m)
	if err != nil {
		return json.RawMessage(`{}`)
	}
	return json.RawMessage(b)
}

// cityWeather — единая схема данных, которую отдаёт collect и принимает report.
// Общий тип гарантирует корректность передачи данных между тулами.
type cityWeather struct {
	Name    string  `json:"name"`
	Country string  `json:"country"`
	Temp    float64 `json:"temp"`
	Wind    float64 `json:"wind"`
	Code    int     `json:"code"`
	Desc    string  `json:"desc"`
}

func registerPipelineTools(s *mcp.Server) {
	// 1) ПОИСК/ПОЛУЧЕНИЕ: собрать текущую погоду по списку городов → {cities:[...]}.
	s.AddTool(&mcp.Tool{
		Name: "weather_collect",
		Description: "Шаг 1 пайплайна. Собирает текущую погоду по списку городов и возвращает " +
			"JSON {\"cities\":[...]}. Этот результат передаётся в make_report.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"locations":{"type":"array","items":{"type":"string"},"description":"Города, напр. [\"Берлин\",\"София\"]"},
				"units":{"type":"string","enum":["celsius","fahrenheit"],"default":"celsius"}
			},
			"required":["locations"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Locations []string `json:"locations"`
			Units     string   `json:"units"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(err), nil
		}
		if in.Units == "" {
			in.Units = "celsius"
		}
		cities := make([]cityWeather, 0, len(in.Locations))
		for _, loc := range in.Locations {
			places, err := geocode(ctx, loc, 1)
			if err != nil || len(places) == 0 {
				continue // пропускаем ненайденные, не роняя весь пайплайн
			}
			p := places[0]
			w, err := currentWeather(ctx, p.Lat, p.Lon, in.Units)
			if err != nil {
				continue
			}
			cities = append(cities, cityWeather{
				Name: p.Name, Country: p.Country,
				Temp: w.Temp, Wind: w.Wind, Code: w.Code, Desc: weatherCodeText(w.Code),
			})
		}
		out, _ := json.Marshal(struct {
			Cities []cityWeather `json:"cities"`
		}{cities})
		return textResult(string(out)), nil
	})

	// 2) ОБРАБОТКА: из собранных данных сделать текстовый отчёт (итог). Без LLM.
	s.AddTool(&mcp.Tool{
		Name: "make_report",
		Description: "Шаг 2 пайплайна. Принимает cities (из weather_collect) и формирует " +
			"текстовый отчёт: рейтинг по температуре, экстремумы, среднее. Результат можно сохранить тулом save_to_file (сервер notes).",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"cities":{"type":"array","description":"Массив из weather_collect (поле cities)",
					"items":{"type":"object","properties":{
						"name":{"type":"string"},"country":{"type":"string"},
						"temp":{"type":"number"},"wind":{"type":"number"},
						"code":{"type":"integer"},"desc":{"type":"string"}}}},
				"title":{"type":"string","description":"Заголовок отчёта (необязательно)"}
			},
			"required":["cities"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Cities []cityWeather `json:"cities"`
			Title  string        `json:"title"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(err), nil
		}
		if len(in.Cities) == 0 {
			return textResult("нет данных для отчёта"), nil
		}
		return textResult(buildReport(in.Cities, in.Title)), nil
	})

}

func buildReport(cities []cityWeather, title string) string {
	sorted := make([]cityWeather, len(cities))
	copy(sorted, cities)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].Temp > sorted[j].Temp })

	var b strings.Builder
	if title == "" {
		title = "Погодный отчёт"
	}
	fmt.Fprintf(&b, "%s\n%s\n\n", title, strings.Repeat("=", len([]rune(title))))
	fmt.Fprintf(&b, "Городов: %d\n\n", len(sorted))

	sum := 0.0
	for i, c := range sorted {
		fmt.Fprintf(&b, "%d. %s, %s — %.1f°C, ветер %.0f км/ч, %s\n",
			i+1, c.Name, c.Country, c.Temp, c.Wind, c.Desc)
		sum += c.Temp
	}
	warm, cold := sorted[0], sorted[len(sorted)-1]
	fmt.Fprintf(&b, "\nТеплее всего: %s (%.1f°C) · холоднее всего: %s (%.1f°C) · средняя %.1f°C\n",
		warm.Name, warm.Temp, cold.Name, cold.Temp, sum/float64(len(sorted)))
	return b.String()
}

// sourceDir — каталог этого файла (рядом кладём weather-store.json).
func sourceDir() string {
	if _, file, _, ok := runtime.Caller(0); ok {
		return filepath.Dir(file)
	}
	return "."
}

func main() {
	// День 18: персистентное хранилище рядом с сервером + контекст для фоновых сборщиков.
	store := loadStore(filepath.Join(sourceDir(), "weather-store.json"))
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	// Возобновляем периодический сбор по уже отслеживаемым городам (после рестарта).
	sched := NewScheduler(ctx, store)
	for _, t := range store.List() {
		sched.Start(t)
		log.Printf("[collector] возобновлён сбор: %s каждые %d с", t.Name, t.IntervalSec)
	}

	s := mcp.NewServer(&mcp.Implementation{Name: "weather-mcp", Version: "0.2.0"}, nil)

	// --- Инструмент 1: geocode (название -> координаты) ---
	s.AddTool(&mcp.Tool{
		Name:        "geocode",
		Description: "Найти координаты населённого пункта по названию (open-meteo geocoding).",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"name":{"type":"string","description":"Название города, напр. 'Берлин' или 'Sofia'"},
				"count":{"type":"integer","description":"Сколько результатов вернуть (1-10)","default":1}
			},
			"required":["name"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Name  string `json:"name"`
			Count int    `json:"count"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(fmt.Errorf("не разобрал аргументы: %w", err)), nil
		}
		if in.Count <= 0 {
			in.Count = 1
		}
		places, err := geocode(ctx, in.Name, in.Count)
		if err != nil {
			return errResult(err), nil
		}
		if len(places) == 0 {
			return textResult("ничего не найдено по запросу: " + in.Name), nil
		}
		var b strings.Builder
		for _, p := range places {
			fmt.Fprintf(&b, "%s, %s — lat=%.4f lon=%.4f\n", p.Name, p.Country, p.Lat, p.Lon)
		}
		return textResult(strings.TrimRight(b.String(), "\n")), nil
	})

	// --- Инструмент 2: weather_current (город -> текущая погода) ---
	s.AddTool(&mcp.Tool{
		Name:        "weather_current",
		Description: "Текущая погода в городе: геокодит название и берёт текущие показатели open-meteo.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"location":{"type":"string","description":"Город, напр. 'Берлин' или 'Sofia'"},
				"units":{"type":"string","enum":["celsius","fahrenheit"],"description":"Единицы температуры","default":"celsius"}
			},
			"required":["location"]
		}`),
	}, func(ctx context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Location string `json:"location"`
			Units    string `json:"units"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(fmt.Errorf("не разобрал аргументы: %w", err)), nil
		}
		if in.Units == "" {
			in.Units = "celsius"
		}
		places, err := geocode(ctx, in.Location, 1)
		if err != nil {
			return errResult(err), nil
		}
		if len(places) == 0 {
			return textResult("город не найден: " + in.Location), nil
		}
		p := places[0]
		w, err := currentWeather(ctx, p.Lat, p.Lon, in.Units)
		if err != nil {
			return errResult(err), nil
		}
		deg := "°C"
		if in.Units == "fahrenheit" {
			deg = "°F"
		}
		out := fmt.Sprintf("%s, %s: %.1f%s, ветер %.0f км/ч, %s",
			p.Name, p.Country, w.Temp, deg, w.Wind, weatherCodeText(w.Code))
		return textResult(out), nil
	})

	// День 18: тулы планировщика/фоновых задач.
	registerScheduledTools(sched, s, store)

	// День 19: пайплайн-тулы (collect → report → save).
	registerPipelineTools(s)

	// Run обслуживает stdio до закрытия соединения клиентом.
	if err := s.Run(ctx, &mcp.StdioTransport{}); err != nil {
		log.Fatal(err)
	}
}

// registerScheduledTools регистрирует тулы дня 18 на сервере.
func registerScheduledTools(sched *Scheduler, s *mcp.Server, store *Store) {
	// track_location — отложенно/периодически собирать погоду по городу.
	s.AddTool(&mcp.Tool{
		Name:        "track_location",
		Description: "Начать периодический фоновый сбор погоды по городу (сохраняется в JSON). Возвращает подтверждение.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"location":{"type":"string","description":"Город, напр. 'Берлин'"},
				"interval_sec":{"type":"integer","description":"Период сбора в секундах (мин. 5)","default":60}
			},
			"required":["location"]
		}`),
	}, func(ctx2 context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Location    string `json:"location"`
			IntervalSec int    `json:"interval_sec"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(err), nil
		}
		if in.IntervalSec < 5 {
			in.IntervalSec = 60
		}
		places, err := geocode(ctx2, in.Location, 1)
		if err != nil {
			return errResult(err), nil
		}
		if len(places) == 0 {
			return textResult("город не найден: " + in.Location), nil
		}
		p := places[0]
		t := &Tracked{
			Location: in.Location, Name: p.Name, Country: p.Country,
			Lat: p.Lat, Lon: p.Lon, IntervalSec: in.IntervalSec,
		}
		store.Upsert(t)
		sched.Start(t) // живёт после ответа, пока жив сервер
		return textResult(fmt.Sprintf("слежу за %s, %s — сбор каждые %d с (данные в weather-store.json)",
			p.Name, p.Country, in.IntervalSec)), nil
	})

	// weather_summary — агрегированный результат по накопленным наблюдениям.
	s.AddTool(&mcp.Tool{
		Name:        "weather_summary",
		Description: "Агрегированная сводка по собранным наблюдениям (кол-во, период, min/avg/max температуры). Без location — по всем городам.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{
				"location":{"type":"string","description":"Город; пусто = по всем отслеживаемым"}
			}
		}`),
	}, func(ctx2 context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Location string `json:"location"`
		}
		_ = json.Unmarshal(req.Params.Arguments, &in)
		return textResult(store.Summary(in.Location)), nil
	})

	// list_tracked — что сейчас отслеживается.
	s.AddTool(&mcp.Tool{
		Name:        "list_tracked",
		Description: "Список городов, по которым идёт фоновый сбор, и их интервалы.",
		InputSchema: json.RawMessage(`{"type":"object"}`),
	}, func(ctx2 context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		ts := store.List()
		if len(ts) == 0 {
			return textResult("ничего не отслеживается"), nil
		}
		var b strings.Builder
		for _, t := range ts {
			fmt.Fprintf(&b, "%s, %s — каждые %d с, наблюдений: %d\n", t.Name, t.Country, t.IntervalSec, len(t.Samples))
		}
		return textResult(strings.TrimRight(b.String(), "\n")), nil
	})

	// untrack_location — снять город с фонового сбора (останавливает горутину).
	s.AddTool(&mcp.Tool{
		Name:        "untrack_location",
		Description: "Прекратить фоновый сбор по городу. Можно указать название как при добавлении.",
		InputSchema: json.RawMessage(`{
			"type":"object",
			"properties":{"location":{"type":"string","description":"Город, который перестать отслеживать"}},
			"required":["location"]
		}`),
	}, func(ctx2 context.Context, req *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
		var in struct {
			Location string `json:"location"`
		}
		if err := json.Unmarshal(req.Params.Arguments, &in); err != nil {
			return errResult(err), nil
		}
		key, name, ok := store.Remove(in.Location)
		if !ok {
			return textResult("не отслеживается: " + in.Location), nil
		}
		sched.Stop(key)
		return textResult("снят с отслеживания: " + name), nil
	})
}

type place struct {
	Name    string
	Country string
	Lat     float64
	Lon     float64
}

func geocode(ctx context.Context, name string, count int) ([]place, error) {
	q := url.Values{}
	q.Set("name", name)
	q.Set("count", strconv.Itoa(count))
	q.Set("language", "ru")
	q.Set("format", "json")
	u := "https://geocoding-api.open-meteo.com/v1/search?" + q.Encode()

	var resp struct {
		Results []struct {
			Name      string  `json:"name"`
			Country   string  `json:"country"`
			Latitude  float64 `json:"latitude"`
			Longitude float64 `json:"longitude"`
		} `json:"results"`
	}
	if err := getJSON(ctx, u, &resp); err != nil {
		return nil, err
	}
	out := make([]place, 0, len(resp.Results))
	for _, r := range resp.Results {
		out = append(out, place{Name: r.Name, Country: r.Country, Lat: r.Latitude, Lon: r.Longitude})
	}
	return out, nil
}

type weather struct {
	Temp float64
	Wind float64
	Code int
}

func currentWeather(ctx context.Context, lat, lon float64, units string) (weather, error) {
	q := url.Values{}
	q.Set("latitude", strconv.FormatFloat(lat, 'f', 4, 64))
	q.Set("longitude", strconv.FormatFloat(lon, 'f', 4, 64))
	q.Set("current", "temperature_2m,wind_speed_10m,weather_code")
	q.Set("temperature_unit", units)
	u := "https://api.open-meteo.com/v1/forecast?" + q.Encode()

	var resp struct {
		Current struct {
			Temp float64 `json:"temperature_2m"`
			Wind float64 `json:"wind_speed_10m"`
			Code int     `json:"weather_code"`
		} `json:"current"`
	}
	if err := getJSON(ctx, u, &resp); err != nil {
		return weather{}, err
	}
	return weather{Temp: resp.Current.Temp, Wind: resp.Current.Wind, Code: resp.Current.Code}, nil
}

func getJSON(ctx context.Context, u string, dst any) error {
	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
	if err != nil {
		return err
	}
	req.Header.Set("User-Agent", userAgent)
	res, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer res.Body.Close()
	if res.StatusCode != http.StatusOK {
		body, _ := io.ReadAll(io.LimitReader(res.Body, 512))
		return fmt.Errorf("open-meteo вернул %d: %s", res.StatusCode, strings.TrimSpace(string(body)))
	}
	return json.NewDecoder(res.Body).Decode(dst)
}

func textResult(s string) *mcp.CallToolResult {
	return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: s}}}
}

func errResult(err error) *mcp.CallToolResult {
	return &mcp.CallToolResult{
		IsError: true,
		Content: []mcp.Content{&mcp.TextContent{Text: "ошибка: " + err.Error()}},
	}
}

import (
	"context"
	"log"
	"sync"
	"time"
)

// Scheduler управляет фоновыми сборщиками: по одному на город (ключ — координаты).
// При повторном Start для того же ключа старый сборщик останавливается (без дублей).
type Scheduler struct {
	mu      sync.Mutex
	base    context.Context
	store   *Store
	cancels map[string]context.CancelFunc
}

func NewScheduler(base context.Context, store *Store) *Scheduler {
	return &Scheduler{base: base, store: store, cancels: map[string]context.CancelFunc{}}
}

// Start (пере)запускает сбор по городу: сразу + далее каждые IntervalSec секунд.
func (s *Scheduler) Start(t *Tracked) {
	key := t.key()
	s.mu.Lock()
	if cancel, ok := s.cancels[key]; ok {
		cancel() // останавливаем прежний сборщик этого города
	}
	ctx, cancel := context.WithCancel(s.base)
	s.cancels[key] = cancel
	s.mu.Unlock()

	go s.run(ctx, key, t)
}

// Stop останавливает сборщик по ключу.
func (s *Scheduler) Stop(key string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if cancel, ok := s.cancels[key]; ok {
		cancel()
		delete(s.cancels, key)
	}
}

func (s *Scheduler) run(ctx context.Context, key string, t *Tracked) {
	collect(ctx, s.store, key, t)
	iv := t.IntervalSec
	if iv <= 0 {
		iv = 60
	}
	ticker := time.NewTicker(time.Duration(iv) * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if !s.store.Has(key) { // город сняли с отслеживания — выходим
				return
			}
			collect(ctx, s.store, key, t)
		}
	}
}

func collect(ctx context.Context, store *Store, key string, t *Tracked) {
	w, err := currentWeather(ctx, t.Lat, t.Lon, "celsius")
	if err != nil {
		log.Printf("[collector] %s: ошибка сбора: %v", t.Name, err)
		return
	}
	store.Append(key, Sample{Time: time.Now(), Temp: w.Temp, Wind: w.Wind, Code: w.Code})
	log.Printf("[collector] %s: %.1f°C записано", t.Name, w.Temp)
}

type Sample struct {
	Time time.Time `json:"time"`
	Temp float64   `json:"temp"`
	Wind float64   `json:"wind"`
	Code int       `json:"code"`
}

type Store struct {
	mu      sync.Mutex
	path    string
	Tracked map[string]*Tracked `json:"tracked"`
}

func loadStore(path string) *Store {
	s := &Store{path: path, Tracked: map[string]*Tracked{}}
	data, err := os.ReadFile(path)
	if err != nil {
		return s
	}
	var disk struct {
		Tracked map[string]*Tracked `json:"tracked"`
	}
	if err := json.Unmarshal(data, &disk); err == nil && disk.Tracked != nil {
		s.Tracked = disk.Tracked
	}
	return s
}

func (s *Store) saveLocked() {
	data, err := json.MarshalIndent(struct {
		Tracked map[string]*Tracked `json:"tracked"`
	}{s.Tracked}, "", "  ")
	if err != nil {
		return
	}
	tmp := s.path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return
	}
	_ = os.Rename(tmp, s.path)
}

// Upsert регистрирует/обновляет город по координатному ключу (сохраняя историю).
func (s *Store) Upsert(t *Tracked) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if old, ok := s.Tracked[t.key()]; ok {
		t.Samples = old.Samples
	}
	s.Tracked[t.key()] = t
	s.saveLocked()
}

// Append добавляет наблюдение по координатному ключу.
func (s *Store) Append(key string, smp Sample) {
	s.mu.Lock()
	defer s.mu.Unlock()
	t, ok := s.Tracked[key]
	if !ok {
		return
	}
	t.Samples = append(t.Samples, smp)
	s.saveLocked()
}

// Has сообщает, отслеживается ли ключ (для остановки осиротевших сборщиков).
func (s *Store) Has(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.Tracked[key]
	return ok
}

// Remove удаляет город по вводу/имени (без учёта регистра). Возвращает ключ и имя.
func (s *Store) Remove(query string) (key, name string, ok bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	q := strings.ToLower(strings.TrimSpace(query))
	for k, t := range s.Tracked {
		if strings.ToLower(t.Location) == q || strings.ToLower(t.Name) == q {
			delete(s.Tracked, k)
			s.saveLocked()
			return k, t.Name, true
		}
	}
	return "", "", false
}

// RemoveAll очищает всё отслеживание. Возвращает число удалённых.
func (s *Store) RemoveAll() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := len(s.Tracked)
	s.Tracked = map[string]*Tracked{}
	s.saveLocked()
	return n
}

func (s *Store) List() []*Tracked {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make([]*Tracked, 0, len(s.Tracked))
	for _, t := range s.Tracked {
		out = append(out, t)
	}
	return out
}

// Summary — агрегат. query пуст = по всем; иначе по совпадению ввода/имени.
func (s *Store) Summary(query string) string {
	s.mu.Lock()
	defer s.mu.Unlock()

	pick := func(t *Tracked) string {
		n := len(t.Samples)
		if n == 0 {
			return fmt.Sprintf("%s, %s: наблюдений пока нет (интервал %d с)", t.Name, t.Country, t.IntervalSec)
		}
		min, max, sum := t.Samples[0].Temp, t.Samples[0].Temp, 0.0
		for _, smp := range t.Samples {
			if smp.Temp < min {
				min = smp.Temp
			}
			if smp.Temp > max {
				max = smp.Temp
			}
			sum += smp.Temp
		}
		first, last := t.Samples[0], t.Samples[n-1]
		span := last.Time.Sub(first.Time).Round(time.Second)
		return fmt.Sprintf(
			"%s, %s: наблюдений %d за %s · t сейчас %.1f°C (min %.1f / avg %.1f / max %.1f) · обновление каждые %d с",
			t.Name, t.Country, n, span, last.Temp, min, sum/float64(n), max, t.IntervalSec,
		)
	}

	if q := strings.ToLower(strings.TrimSpace(query)); q != "" {
		for _, t := range s.Tracked {
			if strings.ToLower(t.Location) == q || strings.ToLower(t.Name) == q {
				return pick(t)
			}
		}
		return "город не отслеживается: " + query + " (добавь через track_location)"
	}

	if len(s.Tracked) == 0 {
		return "пока ничего не отслеживается — добавь город через track_location"
	}
	out := "Сводка по отслеживаемым городам:\n"
	for _, t := range s.Tracked {
		out += "  • " + pick(t) + "\n"
	}
	return out
}
